"""Top-level orchestration: config, aliases, rewrite, parse, resolve, validate, run."""

import os
import sys
import time

from . import config_loader, database
from .arguments import END_OF_OPTIONS, is_assoc_token, parse_argv
from .commands import build_command_tree
from .context import Context
from .errors import AppctlError, MultiLineError, UsageError
from .file_cache import get_cache
from .help import render_root_help, render_usage
from .logger import FileLogger, log_path
from .output import Output
from .remote import run_remote
from .resolver import resolve
from .rewrites import apply_rewrites
from .runtime_config import build_runtime_config, deprecation_warnings, is_strict_mode
from .suggest import get_suggestion
from .validator import ArgumentValidator


def extract_alias(argv):
    """Return ``(alias, argv_without_alias)``; the alias is the first non-flag token."""
    for index, token in enumerate(argv):
        if token == END_OF_OPTIONS:
            break
        if is_assoc_token(token):
            continue
        if config_loader.is_alias(token):
            return token, argv[:index] + argv[index + 1:]
        break
    return None, list(argv)


def _unique(items):
    seen = []
    for item in items:
        if item not in seen:
            seen.append(item)
    return seen


def check_disabled(command, typed, disabled):
    """Raise if the command or one of its parents is disabled."""
    disabled = {" ".join(str(entry).split()) for entry in disabled}
    for path in (command.path, typed[:len(command.path)]):
        for depth in range(1, len(path) + 1):
            name = " ".join(path[:depth])
            if name in disabled:
                raise AppctlError(f"The '{name}' command has been disabled.")


def guarded(output, action, *args):
    """Run ``action`` and report user-facing errors; return the exit code."""
    try:
        return int(action(*args) or 0)
    except UsageError as exc:
        output.line(exc.usage)
        return exc.exit_code
    except MultiLineError as exc:
        output.error_multi_line(exc.lines, sensitive=exc.sensitive)
        return exc.exit_code
    except AppctlError as exc:
        output.error(exc.message, sensitive=exc.sensitive)
        return exc.exit_code


def is_completion_request(positional):
    """Tab completion runs ``cli completions``; it is never logged."""
    return list(positional[:2]) == ["cli", "completions"]


class Runner:
    def __init__(self, argv, parsed, environ, output, strict, loaded):
        self.argv = argv
        self.parsed = parsed
        self.environ = environ
        self.output = output
        self.strict = strict
        self.loaded = loaded
        self._root = None

    @property
    def root(self):
        if self._root is None:
            self._root = build_command_tree()
        return self._root

    # -- aliases ----------------------------------------------------------

    def run_alias(self, name, stack=()):
        aliases = self.loaded.aliases
        if name == config_loader.ALL_ALIAS and not aliases:
            raise AppctlError("Cannot use '@all' when no aliases are registered.")
        if name not in aliases:
            message = f"Alias '{name}' not found."
            suggestion = get_suggestion(name, list(aliases))
            if suggestion:
                message += f"\nDid you mean '{suggestion}'?"
            raise AppctlError(message)
        definition = aliases[name]
        if name == config_loader.ALL_ALIAS and definition is None:
            members = sorted((a for a, d in aliases.items() if a != name and not isinstance(d, list)),
                             key=config_loader.alias_sort_key)
            return self.run_group(name, members, stack)
        if isinstance(definition, list):
            members = _unique(definition)
            invalid = [m for m in members if m not in aliases]
            if invalid:
                raise AppctlError(
                    f"Group '{name}' contains one or more invalid aliases: {', '.join(invalid)}."
                )
            return self.run_group(name, members, stack)
        return self.run(name, definition if isinstance(definition, dict) else {})

    def run_group(self, name, members, stack):
        stack = stack + (name,)
        result = 0
        for member in members:
            if member in stack:
                continue
            self.output.log(member)
            self.output.stdout.flush()
            code = guarded(self.output, self.run_alias, member, stack)
            self.output.stdout.flush()
            if code:
                result = code
        return result

    # -- a single execution ----------------------------------------------

    def run(self, alias=None, alias_params=None):
        runtime = build_runtime_config(self.parsed.runtime, self.loaded.merged, alias_params)
        self.output.set_color(runtime.get("color"))
        if runtime.get("ssh"):
            return run_remote(runtime["ssh"], self.argv, self.environ, self.output,
                              alias=alias, alias_params=alias_params,
                              skip_tty=bool(runtime.get("skip-tty")))
        positional = self.parsed.positional
        if not positional:
            self.output.line(render_root_help(self.root))
            return 0
        command, remaining = resolve(self.root, positional)
        check_disabled(command, positional, runtime["disabled_commands"])
        if not command.is_runnable:
            self.output.line(render_usage(command))
            return 0
        self.output.debug(f"Running command: {command.full_name}")
        args, assoc = ArgumentValidator(command).validate(
            remaining, self.parsed.assoc, warn=self.output.warning,
            read_stdin=self.output.read_stdin,
        )
        context = Context(root=self.root, command=command, output=self.output,
                          runtime=runtime, strict=self.strict, config=self.loaded,
                          alias=alias)
        return command.handler(context, args, assoc)


def main(argv=None, environ=None, stdout=None, stderr=None, cwd=None, stdin=None):
    started = time.monotonic()
    argv = sys.argv[1:] if argv is None else list(argv)
    environ = os.environ if environ is None else environ
    strict = is_strict_mode(environ)

    invocation = list(argv)
    alias, argv = extract_alias(argv)
    parsed = parse_argv(apply_rewrites(argv), strict=strict)
    logger = FileLogger(log_path(config_loader.root_dir(environ)),
                        enabled=not is_completion_request(parsed.positional))
    logger.start_invocation(invocation)
    output = Output(quiet=bool(parsed.runtime.get("quiet")), debug=parsed.runtime.get("debug", False),
                    stdout=stdout, stderr=stderr, stdin=stdin,
                    color=parsed.runtime.get("color", "auto"), logger=logger, start_time=started)
    for warning in deprecation_warnings(parsed.runtime):
        print(warning, file=output.stderr)

    def start():
        database.get_db(environ)
        loaded = config_loader.load(environ, cwd)
        output.set_color(build_runtime_config(parsed.runtime, loaded.merged)["color"])
        output.debug(f"Using global config: {loaded.global_path}", group="bootstrap")
        if loaded.project_path:
            output.debug(f"Using project config: {loaded.project_path}", group="bootstrap")
        else:
            output.debug("No project config found.", group="bootstrap")
        runner = Runner(argv, parsed, environ, output, strict, loaded)
        if alias:
            return runner.run_alias(alias)
        return runner.run()

    code = guarded(output, start)
    database.close_all()
    if not is_completion_request(parsed.positional):
        clean_cache(environ, output)
    return code


def clean_cache(environ, output):
    """Deterministic end-of-invocation cache cleanup (expiry, then LRU size limit)."""
    try:
        get_cache(environ, output).clean()
    except Exception:  # cleanup must never affect the command's outcome
        pass
"""``appctl site``: site management (simulated)."""

import re

from ..errors import AppctlError
from ._listing import LIST_OPTIONS, confirm, render_list

SITES = [
    {"name": "blog", "type": "blog", "url": "https://blog.example.test", "status": "active"},
    {"name": "main", "type": "standard", "url": "https://main.example.test", "status": "active"},
    {"name": "shop", "type": "store", "url": "https://shop.example.test", "status": "archived"},
]
FIELDS = ["name", "type", "url", "status"]
SITE_NAME_RE = re.compile(r"^[a-z0-9][a-z0-9-]*$")


def _find(name):
    return next((s for s in SITES if s["name"] == name), None)


def create(ctx, args, assoc):
    name = args[0]
    if not SITE_NAME_RE.match(name):
        raise AppctlError(
            f"Invalid site name '{name}'. Use lowercase letters, numbers and hyphens only."
        )
    if _find(name):
        raise AppctlError(f"Site '{name}' already exists.")
    if assoc.get("porcelain"):
        ctx.output.line(name)
        return
    title = assoc.get("title") or name
    visibility = "private" if assoc.get("private") else "public"
    ctx.output.success(
        f"Site '{name}' created (type: {assoc['type']}, title: {title}, "
        f"email: {assoc['email']}, visibility: {visibility})."
    )


def delete(ctx, args, assoc):
    name = args[0]
    if _find(name) is None:
        raise AppctlError(f"Site '{name}' does not exist.")
    if not confirm(ctx, assoc, f"Are you sure you want to delete the '{name}' site?"):
        return
    suffix = " Database tables were kept." if assoc.get("keep-tables") else ""
    ctx.output.success(f"The site '{name}' was deleted.{suffix}")


def list_(ctx, args, assoc):
    render_list(ctx, SITES, assoc, FIELDS, id_field="name")


def _set_status(status):
    def handler(ctx, args, assoc):
        failed = 0
        for name in args:
            site = _find(name)
            if site is None:
                ctx.output.warning(f"Site '{name}' does not exist.")
                failed += 1
            elif site["status"] == status:
                ctx.output.warning(f"Site '{name}' is already {status}.")
            else:
                ctx.output.success(f"Site '{name}' {status}.")
        return 1 if failed else 0
    return handler


def empty(ctx, args, assoc):
    if not confirm(ctx, assoc, "Are you sure you want to empty the site of all content?"):
        return
    extra = " Uploaded files were removed." if assoc.get("uploads") else ""
    ctx.output.success(f"The site was emptied.{extra}")


def register(registry):
    registry.add("site", description="Creates, deletes, empties, and lists sites.")
    site_option = {"site-name": "The name of the site."}
    registry.add(
        "site activate", _set_status("active"),
        synopsis="<site-name>...",
        description="Activates one or more sites.",
        options=site_option,
    )
    registry.add(
        "site archive", _set_status("archived"),
        synopsis="<site-name>...",
        description="Archives one or more sites.",
        options=site_option,
    )
    registry.add(
        "site create", create,
        synopsis="<site-name> [--type=<type>] [--title=<title>] [--email=<email>] "
                 "[--[no-]private] [--porcelain]",
        description="Creates a site.",
        defaults={"type": "standard", "email": "admin@example.test", "private": False},
        options=dict(site_option, type="The type of site to create.",
                     title="Title of the new site. Defaults to the site name.",
                     email="Email for the site admin.",
                     private="If set, the new site will be non-public.",
                     porcelain="If set, only the site name will be output on success."),
    )
    registry.add(
        "site delete", delete,
        synopsis="<site-name> [--yes] [--keep-tables]",
        description="Deletes a site.",
        options=dict(site_option, yes="Answer yes to the confirmation message.",
                     **{"keep-tables": "Delete the site but keep its database tables."}),
    )
    registry.add(
        "site empty", empty,
        synopsis="[--uploads] [--yes]",
        description="Empties a site of its content.",
        options={"uploads": "Also delete uploaded files.",
                 "yes": "Answer yes to the confirmation message."},
    )
    registry.add(
        "site list", list_,
        synopsis="[--<field>=<value>] [--field=<field>] [--fields=<fields>] [--format=<format>]",
        description="Lists all sites.",
        alias="ls",
        defaults={"format": "table"},
        options=LIST_OPTIONS,
    )
"""Assembly of the full appctl command tree."""

from ..registry import CommandRegistry
from . import cache, cli, config, db, help, option, plugin, post, site, theme, user

COMMAND_MODULES = (cache, cli, config, db, help, option, plugin, post, site, theme, user)


def build_command_tree():
    registry = CommandRegistry(description="Manage applications from the command line.")
    for module in COMMAND_MODULES:
        module.register(registry)
    return registry.root
"""Registration of commands into a tree rooted at the program command."""

from . import PROGRAM_NAME
from .command import Command


class CommandRegistry:
    """Builds the command tree from multi-level command paths."""

    def __init__(self, description=""):
        self.root = Command(PROGRAM_NAME, description=description)

    def add(self, path, handler=None, **attributes):
        """Register ``path`` (e.g. ``"site create"``) and return the command.

        Parent commands must be registered before their subcommands.
        """
        parts = path.split()
        if not parts:
            raise ValueError("A command path cannot be empty")
        parent = self.root
        for index, part in enumerate(parts[:-1]):
            child = parent.subcommands.get(part)
            if child is None:
                missing = " ".join(parts[: index + 1])
                raise ValueError(f"Parent command '{missing}' must be registered before '{path}'")
            parent = child
        return parent.add_subcommand(Command(parts[-1], handler=handler, **attributes))

    def get(self, path):
        node = self.root
        for part in path.split():
            node = node.subcommands[part]
        return node
"""The command tree node."""

from .errors import SynopsisError
from .synopsis import invalid_tokens, parse_synopsis


def sort_key(name):
    """Case-insensitive alphabetical ordering with a stable tie-break."""
    return (name.lower(), name)


class Command:
    """A node in the command tree.

    A command may have a handler, subcommands, or both. A command with
    subcommands but no handler only prints its usage when invoked.
    """

    def __init__(self, name, description="", synopsis="", handler=None,
                 alias=None, defaults=None, options=None, longdesc=""):
        self.name = name
        self.description = description
        self.synopsis = " ".join((synopsis or "").split())
        self.handler = handler
        self.alias = alias
        self.defaults = dict(defaults or {})
        self.options = dict(options or {})
        self.longdesc = longdesc
        self.parent = None
        self.subcommands = {}

        self.tokens = parse_synopsis(self.synopsis)
        bad = invalid_tokens(self.tokens)
        if bad:
            raise SynopsisError(
                f"The '{name}' command has an invalid synopsis part: {', '.join(bad)}"
            )

    # -- tree structure -------------------------------------------------

    def add_subcommand(self, command):
        for taken in self._taken_names():
            if taken in (command.name, command.alias):
                raise ValueError(
                    f"'{taken}' is already registered under '{self.full_name or 'appctl'}'"
                )
        command.parent = self
        self.subcommands[command.name] = command
        return command

    def _taken_names(self):
        for sub in self.subcommands.values():
            yield sub.name
            if sub.alias:
                yield sub.alias

    def find_subcommand(self, token):
        """Match a subcommand by canonical name first, then by alias."""
        if token in self.subcommands:
            return self.subcommands[token]
        for sub in self.subcommands.values():
            if sub.alias and sub.alias == token:
                return sub
        return None

    def sorted_subcommands(self):
        return [self.subcommands[k] for k in sorted(self.subcommands, key=sort_key)]

    def subcommand_names(self):
        return list(self.subcommands)

    # -- properties -----------------------------------------------------

    @property
    def is_root(self):
        return self.parent is None

    @property
    def has_subcommands(self):
        return bool(self.subcommands)

    @property
    def is_runnable(self):
        return self.handler is not None

    @property
    def path(self):
        """Canonical names from the top-level command down to this one."""
        parts = []
        node = self
        while node is not None and not node.is_root:
            parts.append(node.name)
            node = node.parent
        return list(reversed(parts))

    @property
    def full_name(self):
        return " ".join(self.path)

    def tokens_of_type(self, *types):
        return [t for t in self.tokens if t.type in types]

    def __repr__(self):
        return f"Command({self.full_name or '<root>'!r})"
"""Execution context handed to command handlers."""

from dataclasses import dataclass, field


@dataclass
class Context:
    root: object
    command: object
    output: object
    runtime: dict = field(default_factory=dict)
    strict: bool = False
    config: object = None
    alias: str = None
"""Exception types used to signal user-facing failures."""


class AppctlError(Exception):
    """A fatal error reported as ``Error: <message>`` on STDERR.

    A ``sensitive`` error carries user-supplied material and is never
    persisted to the log file.
    """

    def __init__(self, message, exit_code=1, sensitive=False):
        super().__init__(message)
        self.message = message
        self.exit_code = exit_code
        self.sensitive = sensitive


class MultiLineError(AppctlError):
    """A fatal error whose lines are shown in a highlighted box."""

    def __init__(self, lines, exit_code=1, sensitive=False):
        self.lines = [str(line) for line in lines]
        super().__init__("\n".join(self.lines), exit_code, sensitive)


class CommandNotFoundError(AppctlError):
    """Raised when a command or subcommand cannot be resolved."""


class UsageError(AppctlError):
    """Raised when a command must print its usage on STDOUT and fail."""

    def __init__(self, usage, exit_code=1):
        super().__init__(usage, exit_code)
        self.usage = usage


class SynopsisError(ValueError):
    """Raised when a command is registered with a malformed synopsis."""

