"""Execution of external commands, including appctl itself."""

import json
import os
import shlex
import subprocess
import sys
import time
from dataclasses import dataclass, field

from . import PROGRAM_NAME
from .config_loader import CONFIG_PATH_ENV
from .errors import AppctlError
from .runtime_config import GLOBAL_PARAMETERS

OBFUSCATED = "******"
SIGNAL_EXIT_CODE = -1
SIGNAL_WARNING = ("Spawned process returned exit code -1, which could be caused by the "
                  "signal handling configuration of the runtime (e.g. a custom SIGCHLD or "
                  "SIGHUP handler).")
SCRIPT_PATH = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
                           f"{PROGRAM_NAME}.py")


@dataclass
class ProcessRun:
    """Outcome of one external command."""

    stdout: str
    stderr: str
    return_code: int
    command: object
    cwd: str = None
    env: dict = field(default=None, repr=False)
    run_time: float = 0.0

    @property
    def succeeded(self):
        return self.return_code == 0


def command_to_string(command):
    if isinstance(command, (list, tuple)):
        return shlex.join(str(part) for part in command)
    return str(command)


def obfuscate(text, secrets=()):
    """Replace every listed substring of ``text`` with ``******``."""
    text = str(text)
    for secret in sorted({str(s) for s in secrets or () if s not in (None, "")},
                         key=len, reverse=True):
        quoted = shlex.quote(secret)
        if quoted != secret:
            text = text.replace(quoted, OBFUSCATED)
        text = text.replace(secret, OBFUSCATED)
    return text


def _debug(output, text, secrets):
    if output is not None:
        output.debug(obfuscate(text, secrets))


def warn_signal_exit(return_code, output=None):
    """Non-halting warning for processes exiting with code -1."""
    if return_code != SIGNAL_EXIT_CODE:
        return
    if output is not None:
        output.warning(SIGNAL_WARNING)
    else:
        print(f"Warning: {SIGNAL_WARNING}", file=sys.stderr)


def run_command(command, output=None, obfuscate_list=(), cwd=None, env=None, stdin=None):
    """Run ``command`` (a shell string or an argv list) and return a :class:`ProcessRun`.

    The command is logged at debug level before it runs; non-empty STDOUT and
    STDERR and then the return code are logged afterwards. Every substring in
    ``obfuscate_list`` is masked in the log, never in the command itself.
    """
    shell = not isinstance(command, (list, tuple))
    argv = command if shell else [str(part) for part in command]
    _debug(output, f"COMMAND: {command_to_string(command)}", obfuscate_list)
    started = time.monotonic()
    try:
        completed = subprocess.run(argv, shell=shell, cwd=cwd, env=env, input=stdin,
                                   capture_output=True, text=True, errors="replace")
        stdout, stderr, return_code = completed.stdout, completed.stderr, completed.returncode
    except OSError as exc:
        stdout, stderr, return_code = "", f"{exc.strerror or exc}\n", 127
    run_time = time.monotonic() - started
    for label, text in (("STDOUT", stdout), ("STDERR", stderr)):
        if text:
            _debug(output, f"{label}: " + text.strip("\r\n"), obfuscate_list)
    _debug(output, f"RETURN CODE: {return_code}", obfuscate_list)
    warn_signal_exit(return_code, output)
    return ProcessRun(stdout=stdout, stderr=stderr, return_code=return_code, command=command,
                      cwd=cwd, env=env, run_time=run_time)


def exec_command(command, output=None, obfuscate_list=(), cwd=None, env=None, stdin=None):
    """Run ``command`` and return whether it succeeded."""
    return run_command(command, output, obfuscate_list, cwd=cwd, env=env, stdin=stdin).succeeded


def launch(command, output=None, exit_on_error=True, return_detailed=True, obfuscate_list=(),
           cwd=None, env=None):
    """Run ``command``; optionally fail on a non-zero exit.

    Returns the :class:`ProcessRun` or, with ``return_detailed=False``, the
    return code.
    """
    result = run_command(command, output, obfuscate_list, cwd=cwd, env=env)
    if exit_on_error and result.return_code != 0:
        raise AppctlError(_failure_message(result, obfuscate_list),
                          exit_code=result.return_code if result.return_code > 0 else 1)
    return result if return_detailed else result.return_code


def _failure_message(result, secrets=()):
    message = result.stderr.strip()
    if message.startswith("Error: "):
        message = message[len("Error: "):]
    if not message:
        message = (f"Command '{obfuscate(command_to_string(result.command), secrets)}' "
                   f"failed with exit code {result.return_code}.")
    return message


# -- re-dispatching appctl itself ---------------------------------------------


def _flag(name, value):
    if value is True:
        return f"--{name}"
    if value is False:
        return f"--no-{name}"
    return f"--{name}={value}"


def runtime_flags(runtime):
    """Global flags reproducing the current runtime configuration."""
    flags = []
    for name, param in GLOBAL_PARAMETERS.items():
        if not param.runtime or name not in (runtime or {}):
            continue
        value = runtime[name]
        if value is None or value == param.default:
            continue
        if isinstance(value, (list, tuple)):
            flags.extend(_flag(name, item) for item in value)
        else:
            flags.append(_flag(name, value))
    return flags


def self_command(command, args=(), assoc=None, runtime=None):
    """argv that runs appctl ``command`` with the current runtime flags."""
    words = shlex.split(command) if isinstance(command, str) else list(command)
    words += [str(a) for a in args]
    words += [_flag(k, v) for k, v in (assoc or {}).items()]
    return [sys.executable, SCRIPT_PATH] + runtime_flags(runtime) + words


def self_environment(config_path=None, environ=None):
    env = dict(os.environ if environ is None else environ)
    if config_path:
        env[CONFIG_PATH_ENV] = str(config_path)
    return env


def launch_self(ctx, command, args=(), assoc=None, exit_on_error=True, return_detailed=False,
                parse=None, obfuscate_list=(), cwd=None):
    """Run an appctl command in a child process, preserving the runtime config.

    Returns the :class:`ProcessRun` (``return_detailed``) or the return code.
    With ``parse="json"`` the child's STDOUT is decoded as JSON first.
    """
    runtime = getattr(ctx, "runtime", None) or {}
    config = getattr(ctx, "config", None)
    argv = self_command(command, args, assoc, runtime)
    env = self_environment(getattr(config, "global_path", None))
    result = launch(argv, getattr(ctx, "output", None), exit_on_error=exit_on_error,
                    obfuscate_list=obfuscate_list, cwd=cwd, env=env)
    if parse == "json":
        result.stdout = parse_json(result.stdout)
    return result if return_detailed else result.return_code


def runcommand(ctx, command, return_=True, parse=None, exit_error=True, obfuscate_list=()):
    """Run an appctl command and return its result.

    ``return_`` selects ``"all"`` (the :class:`ProcessRun`), ``"stdout"`` (or
    ``True``), ``"stderr"`` or ``"return_code"``. ``parse="json"`` decodes
    STDOUT as JSON before it is returned.
    """
    result = launch_self(ctx, command, exit_on_error=exit_error, return_detailed=True,
                         parse=parse, obfuscate_list=obfuscate_list)
    if return_ == "all":
        return result
    if return_ == "stderr":
        return result.stderr.strip()
    if return_ == "return_code":
        return result.return_code
    if parse == "json":
        return result.stdout
    return result.stdout.strip()


def parse_json(text):
    """Decode JSON output; ``None`` when it is not valid JSON."""
    try:
        return json.loads(text)
    except (TypeError, ValueError):
        return None
"""Global runtime configuration parameters."""

import copy
from dataclasses import dataclass

STRICT_ARGS_ENV = "APPCTL_STRICT_ARGS_MODE"


@dataclass(frozen=True)
class GlobalParameter:
    name: str
    synopsis: str
    description: str
    default: object = None
    runtime: bool = True
    file: bool = True
    multiple: bool = False
    deprecated: str = None
    hidden: bool = False


def _file_only(name, description, default=None):
    return GlobalParameter(name, "", description, default, runtime=False, file=True)


GLOBAL_PARAMETERS = {
    p.name: p
    for p in (
        GlobalParameter("path", "--path=<path>", "Path to the application files.", None),
        GlobalParameter("url", "--url=<url>", "Pretend request came from given URL.", None),
        GlobalParameter("ssh", "--ssh=<[scheme:][user@]host|container>[:port][path]",
                        "Perform operation against a remote server over SSH.", None),
        GlobalParameter("http", "--http=<http>", "Perform operation against a remote install over HTTP.", None),
        GlobalParameter("user", "--user=<id|login|email>", "Set the user for the current request.", None),
        GlobalParameter("skip-plugins", "--skip-plugins[=<plugins>]", "Skip loading all or some plugins.", False),
        GlobalParameter("skip-themes", "--skip-themes[=<themes>]", "Skip loading all or some themes.", False),
        GlobalParameter("skip-packages", "--skip-packages", "Skip loading all installed packages.", False),
        GlobalParameter("require", "--require=<path>", "Load a file before running the command.", None),
        GlobalParameter("exec", "--exec=<php-code>", "Execute code before running the command.", None),
        GlobalParameter("context", "--context=<context>", "Load the application in a given context.", "cli"),
        _file_only("disabled_commands", "(Sub)commands to disable.", []),
        _file_only("projects_path", "Path where projects are stored."),
        _file_only("locale", "Locale to use.", "en_US"),
        _file_only("cert-email", "Email address used for certificate registration."),
        _file_only("env", "Environment the tool runs in."),
        _file_only("admin-email", "Email address of the administrator."),
        _file_only("sysctl", "Kernel parameters applied to containers."),
        _file_only("skip-tty", "Never allocate a TTY for remote commands.", False),
        _file_only("custom-compose", "Path to a custom compose file."),
        _file_only("installer_version", "Release channel of the installer.", "stable"),
        GlobalParameter("color", "--[no-]color", "Whether to colorize the output.", "auto"),
        GlobalParameter("debug", "--debug[=<group>]", "Show all errors and debug messages.", False,
                        file=False),
        GlobalParameter("prompt", "--prompt[=<assoc>]", "Prompt the user to enter values for all arguments.",
                        False, file=False),
        GlobalParameter("quiet", "--quiet", "Suppress informational messages.", False, file=False),
    )
}


def is_global_parameter(key):
    """True for global parameters that may be given as runtime flags."""
    param = GLOBAL_PARAMETERS.get(key)
    return param is not None and param.runtime


def is_file_parameter(key):
    param = GLOBAL_PARAMETERS.get(key)
    return param is not None and param.file


def visible_parameters():
    """Global parameters that may be shown in help output."""
    return {name: p for name, p in GLOBAL_PARAMETERS.items() if not p.hidden}


def deprecation_warnings(supplied):
    """Warning lines for every deprecated parameter used as a runtime flag."""
    return [
        f"Warning: The --{key} global parameter is deprecated."
        for key in supplied
        if key in GLOBAL_PARAMETERS and GLOBAL_PARAMETERS[key].deprecated is not None
    ]


def is_strict_mode(environ):
    return bool(environ.get(STRICT_ARGS_ENV))


def _arrayify(value):
    if value is None:
        return []
    return list(value) if isinstance(value, (list, tuple)) else [value]


def build_runtime_config(supplied, *layers):
    """Merge configuration over the defaults.

    ``layers`` are file-derived mappings from lowest to highest precedence
    (e.g. global config, project config, alias); only recognized
    file parameters are taken from them. ``supplied`` holds the runtime
    flags, which win over everything.
    """
    config = {name: copy.deepcopy(param.default) for name, param in GLOBAL_PARAMETERS.items()}
    for layer in layers:
        for key, value in (layer or {}).items():
            if is_file_parameter(key):
                config[key] = value
    config.update(supplied)
    config["disabled_commands"] = [str(c) for c in _arrayify(config.get("disabled_commands"))]
    return config
"""Loading of global/project YAML config files and alias definitions."""

import json
import os
import re
from dataclasses import dataclass, field

import yaml

from .errors import AppctlError

CONFIG_PATH_ENV = "APPCTL_CONFIG_PATH"
ROOT_DIR_ENV = "APPCTL_ROOT_DIR"
PACKAGES_DIR_ENV = "APPCTL_PACKAGES_DIR"
RUNTIME_ALIAS_ENV = "APPCTL_RUNTIME_ALIAS"

PROJECT_CONFIG_FILES = ("appctl.local.yml", "appctl.yml")
ALIAS_RE = re.compile(r"^@[A-Za-z0-9_.\-]+$")
ALL_ALIAS = "@all"
META_KEY = "_"

# Keys the global config file must always define, with their defaults.
REQUIRED_GLOBAL_KEYS = (("locale", "en_US"), ("installer_version", "stable"))


def is_alias(name):
    return isinstance(name, str) and bool(ALIAS_RE.match(name))


def alias_sort_key(name):
    return (name.lower(), name)


# -- locations -----------------------------------------------------------


def root_dir(environ):
    value = environ.get(ROOT_DIR_ENV)
    if value:
        return value
    return os.path.join(os.path.expanduser("~"), ".appctl")


def global_config_path(environ):
    value = environ.get(CONFIG_PATH_ENV)
    if value:
        return value
    return os.path.join(root_dir(environ), "config", "config.yml")


def packages_dir(environ):
    value = environ.get(PACKAGES_DIR_ENV)
    if value:
        return value
    return os.path.join(root_dir(environ), "packages")


def find_project_config(cwd):
    """Search upward from ``cwd``; the first directory with a config wins."""
    directory = os.path.abspath(cwd)
    while True:
        for name in PROJECT_CONFIG_FILES:
            candidate = os.path.join(directory, name)
            if os.path.isfile(candidate):
                return candidate
        parent = os.path.dirname(directory)
        if parent == directory:
            return None
        directory = parent


# -- auto-creation ---------------------------------------------------------


def _read_mapping(path):
    with open(path, encoding="utf-8") as handle:
        text = handle.read()
    try:
        data = yaml.safe_load(text)
    except yaml.YAMLError as exc:
        raise AppctlError(f"Unable to parse the config file '{path}': {exc}") from exc
    if data is None:
        data = {}
    if not isinstance(data, dict):
        raise AppctlError(f"The config file '{path}' must contain a YAML mapping.")
    return data, text


def ensure_global_config(path, strict=True):
    """Add missing required keys to the global config file, creating it.

    Write failures raise :class:`AppctlError` unless ``strict`` is false.
    """
    try:
        if os.path.exists(path):
            data, text = _read_mapping(path)
        else:
            data, text = {}, ""
        missing = [(k, v) for k, v in REQUIRED_GLOBAL_KEYS if k not in data]
        if not missing:
            return
        if text and not text.endswith("\n"):
            text += "\n"
        text += "".join(f"{key}: {value}\n" for key, value in missing)
        directory = os.path.dirname(path)
        if directory:
            os.makedirs(directory, exist_ok=True)
        with open(path, "w", encoding="utf-8") as handle:
            handle.write(text)
    except OSError as exc:
        if strict:
            reason = exc.strerror or str(exc)
            raise AppctlError(f"Unable to write the config file '{path}': {reason}.") from exc


# -- YAML loading with inheritance -------------------------------------------


def _merge(base, override, append_arrays):
    """Overlay ``override`` on ``base``; nested mappings merge recursively."""
    if isinstance(base, dict) and isinstance(override, dict):
        merged = dict(base)
        for key, value in override.items():
            merged[key] = _merge(base[key], value, append_arrays) if key in base else value
        return merged
    if append_arrays and isinstance(base, list) and isinstance(override, list):
        return base + override
    return override


def _absolutize_alias_paths(data, directory):
    for key, value in data.items():
        if is_alias(key) and isinstance(value, dict):
            path = value.get("path")
            if isinstance(path, str) and path and "ssh" not in value:
                value["path"] = os.path.normpath(os.path.join(directory, os.path.expanduser(path)))


def load_config_file(path, accumulated=None, _seen=None):
    """Merge the YAML file at ``path`` (and its ancestors) over ``accumulated``."""
    accumulated = dict(accumulated or {})
    if not path:
        return accumulated
    path = os.path.abspath(path)
    seen = set(_seen or ())
    if path in seen or not os.path.isfile(path):
        return accumulated
    seen.add(path)
    try:
        data, _ = _read_mapping(path)
    except OSError:
        return accumulated
    directory = os.path.dirname(path)
    meta = data.pop(META_KEY, None)
    meta = meta if isinstance(meta, dict) else {}
    inherit = meta.get("inherit")
    if isinstance(inherit, str) and inherit:
        base = os.path.join(directory, os.path.expanduser(inherit))
        accumulated = load_config_file(base, accumulated, seen)
    _absolutize_alias_paths(data, directory)
    return _merge(accumulated, data, meta.get("merge") is True)


# -- aliases -------------------------------------------------------------------


def runtime_aliases(environ, cwd):
    raw = environ.get(RUNTIME_ALIAS_ENV)
    if not raw:
        return {}
    try:
        decoded = json.loads(raw)
    except ValueError:
        return {}
    if not isinstance(decoded, dict):
        return {}
    aliases = {k: v for k, v in decoded.items() if is_alias(k)}
    _absolutize_alias_paths(aliases, cwd)
    return aliases


def collect_aliases(config, extra=None):
    """Return ``{name: definition}``, registering ``@all`` when needed.

    A definition is either a mapping of connection parameters or a list
    of alias names (a group).
    """
    aliases = {}
    for key, value in list(config.items()) + list((extra or {}).items()):
        if not is_alias(key):
            continue
        if isinstance(value, list):
            aliases[key] = [str(v) for v in value]
        elif isinstance(value, dict):
            aliases[key] = dict(value)
        elif value is None:
            aliases[key] = {}
        else:
            aliases[key] = value
    if aliases and ALL_ALIAS not in aliases:
        aliases[ALL_ALIAS] = None  # implicit: every registered alias
    return aliases


# -- entry point ---------------------------------------------------------------


@dataclass
class LoadedConfig:
    global_path: str = None
    project_path: str = None
    global_config: dict = field(default_factory=dict)
    merged: dict = field(default_factory=dict)
    aliases: dict = field(default_factory=dict)
    packages_dir: str = None


def load(environ, cwd=None):
    cwd = cwd or os.getcwd()
    global_path = global_config_path(environ)
    explicit = bool(environ.get(CONFIG_PATH_ENV) or environ.get(ROOT_DIR_ENV))
    ensure_global_config(global_path, strict=explicit)
    global_config = load_config_file(global_path)
    project_path = find_project_config(cwd)
    if project_path and os.path.abspath(project_path) == os.path.abspath(global_path):
        project_path = None
    merged = load_config_file(project_path, global_config)
    return LoadedConfig(
        global_path=global_path,
        project_path=project_path,
        global_config=global_config,
        merged=merged,
        aliases=collect_aliases(merged, runtime_aliases(environ, cwd)),
        packages_dir=packages_dir(environ),
    )
"""Append-only file log of every invocation at ``<root>/logs/appctl.log``."""

import os
import re
import shlex
from datetime import datetime, timezone

from . import PROGRAM_NAME

LOG_DIR = "logs"
LOG_FILE = f"{PROGRAM_NAME}.log"
DELIMITER = "-" * 72
REDACTED = "[REDACTED]"

# ``--key=value`` arguments whose value must never reach the disk.
SENSITIVE_KEY_RE = re.compile(r"pass|pwd|secret|token|api[-_]?key|private[-_]?key|auth|credential",
                              re.IGNORECASE)


def log_path(root_dir):
    return os.path.join(root_dir, LOG_DIR, LOG_FILE)


def utc_timestamp(now=None):
    """ISO 8601 UTC timestamp with second precision, e.g. ``2024-01-31T12:00:00Z``."""
    now = now or datetime.now(timezone.utc)
    return now.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def redact_argv(argv):
    """Replace the values of sensitive ``--key=value`` arguments."""
    redacted = []
    for index, token in enumerate(argv):
        if token == "--":
            redacted.extend(argv[index:])
            break
        if token.startswith("--") and "=" in token:
            key = token[2:].split("=", 1)[0]
            if SENSITIVE_KEY_RE.search(key):
                token = f"--{key}={REDACTED}"
        redacted.append(token)
    return redacted


class FileLogger:
    """Writes timestamped entries; write failures silently disable logging."""

    def __init__(self, path, enabled=True):
        self.path = path
        self.enabled = bool(enabled and path)

    def start_invocation(self, argv):
        """Write the delimiter line and the (redacted) command line."""
        command = shlex.join([PROGRAM_NAME] + redact_argv(list(argv)))
        self._append(f"{DELIMITER}\n[{utc_timestamp()}] Command: {command}\n")

    def write(self, text):
        """Append one entry; every line of it carries the timestamp."""
        stamp = utc_timestamp()
        self._append("".join(f"[{stamp}] {line}\n" for line in str(text).split("\n")))

    def _append(self, data):
        if not self.enabled:
            return
        try:
            directory = os.path.dirname(self.path)
            if directory:
                os.makedirs(directory, exist_ok=True)
            with open(self.path, "a", encoding="utf-8") as handle:
                handle.write(data)
        except OSError:
            self.enabled = False
"""Splitting raw argv into positional, associative and global arguments."""

from dataclasses import dataclass, field

from .runtime_config import is_global_parameter

END_OF_OPTIONS = "--"


def is_assoc_token(token):
    """True for ``--key``, ``--key=value`` and ``--no-key`` tokens."""
    return token.startswith("--") and len(token) > 2


def parse_assoc_token(token):
    """Return ``(key, value)`` for an associative token.

    ``--key=value`` yields the string value, ``--no-key`` yields ``False``
    and a bare ``--key`` yields ``True``.
    """
    body = token[2:]
    if "=" in body:
        key, value = body.split("=", 1)
        return key, value
    if body.startswith("no-"):
        return body[3:], False
    return body, True


@dataclass
class ParsedArguments:
    positional: list = field(default_factory=list)
    assoc: dict = field(default_factory=dict)
    runtime: dict = field(default_factory=dict)


def parse_argv(argv, strict=False):
    """Classify every argv token.

    Global parameters become runtime configuration. In strict mode only
    those appearing before the first positional token are treated as
    global; afterwards every argument is command-specific.
    """
    parsed = ParsedArguments()
    end_of_options = False
    seen_positional = False
    for token in argv:
        if not end_of_options and token == END_OF_OPTIONS:
            end_of_options = True
            continue
        if end_of_options or not is_assoc_token(token):
            parsed.positional.append(token)
            seen_positional = True
            continue
        key, value = parse_assoc_token(token)
        if is_global_parameter(key) and not (strict and seen_positional):
            parsed.runtime[key] = value
        else:
            parsed.assoc[key] = value
    return parsed

tool_use_result.stdout:
"""Execution of external commands, including appctl itself."""

import json
import os
import shlex
import subprocess
import sys
import time
from dataclasses import dataclass, field

from . import PROGRAM_NAME
from .config_loader import CONFIG_PATH_ENV
from .errors import AppctlError
from .runtime_config import GLOBAL_PARAMETERS

OBFUSCATED = "******"
SIGNAL_EXIT_CODE = -1
SIGNAL_WARNING = ("Spawned process returned exit code -1, which could be caused by the "
                  "signal handling configuration of the runtime (e.g. a custom SIGCHLD or "
                  "SIGHUP handler).")
SCRIPT_PATH = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
                           f"{PROGRAM_NAME}.py")


@dataclass
class ProcessRun:
    """Outcome of one external command."""

    stdout: str
    stderr: str
    return_code: int
    command: object
    cwd: str = None
    env: dict = field(default=None, repr=False)
    run_time: float = 0.0

    @property
    def succeeded(self):
        return self.return_code == 0


def command_to_string(command):
    if isinstance(command, (list, tuple)):
        return shlex.join(str(part) for part in command)
    return str(command)


def obfuscate(text, secrets=()):
    """Replace every listed substring of ``text`` with ``******``."""
    text = str(text)
    for secret in sorted({str(s) for s in secrets or () if s not in (None, "")},
                         key=len, reverse=True):
        quoted = shlex.quote(secret)
        if quoted != secret:
            text = text.replace(quoted, OBFUSCATED)
        text = text.replace(secret, OBFUSCATED)
    return text


def _debug(output, text, secrets):
    if output is not None:
        output.debug(obfuscate(text, secrets))


def warn_signal_exit(return_code, output=None):
    """Non-halting warning for processes exiting with code -1."""
    if return_code != SIGNAL_EXIT_CODE:
        return
    if output is not None:
        output.warning(SIGNAL_WARNING)
    else:
        print(f"Warning: {SIGNAL_WARNING}", file=sys.stderr)


def run_command(command, output=None, obfuscate_list=(), cwd=None, env=None, stdin=None):
    """Run ``command`` (a shell string or an argv list) and return a :class:`ProcessRun`.

    The command is logged at debug level before it runs; non-empty STDOUT and
    STDERR and then the return code are logged afterwards. Every substring in
    ``obfuscate_list`` is masked in the log, never in the command itself.
    """
    shell = not isinstance(command, (list, tuple))
    argv = command if shell else [str(part) for part in command]
    _debug(output, f"COMMAND: {command_to_string(command)}", obfuscate_list)
    started = time.monotonic()
    try:
        completed = subprocess.run(argv, shell=shell, cwd=cwd, env=env, input=stdin,
                                   capture_output=True, text=True, errors="replace")
        stdout, stderr, return_code = completed.stdout, completed.stderr, completed.returncode
    except OSError as exc:
        stdout, stderr, return_code = "", f"{exc.strerror or exc}\n", 127
    run_time = time.monotonic() - started
    for label, text in (("STDOUT", stdout), ("STDERR", stderr)):
        if text:
            _debug(output, f"{label}: " + text.strip("\r\n"), obfuscate_list)
    _debug(output, f"RETURN CODE: {return_code}", obfuscate_list)
    warn_signal_exit(return_code, output)
    return ProcessRun(stdout=stdout, stderr=stderr, return_code=return_code, command=command,
                      cwd=cwd, env=env, run_time=run_time)


def exec_command(command, output=None, obfuscate_list=(), cwd=None, env=None, stdin=None):
    """Run ``command`` and return whether it succeeded."""
    return run_command(command, output, obfuscate_list, cwd=cwd, env=env, stdin=stdin).succeeded


def launch(command, output=None, exit_on_error=True, return_detailed=True, obfuscate_list=(),
           cwd=None, env=None):
    """Run ``command``; optionally fail on a non-zero exit.

    Returns the :class:`ProcessRun` or, with ``return_detailed=False``, the
    return code.
    """
    result = run_command(command, output, obfuscate_list, cwd=cwd, env=env)
    if exit_on_error and result.return_code != 0:
        raise AppctlError(_failure_message(result, obfuscate_list),
                          exit_code=result.return_code if result.return_code > 0 else 1)
    return result if return_detailed else result.return_code


def _failure_message(result, secrets=()):
    message = result.stderr.strip()
    if message.startswith("Error: "):
        message = message[len("Error: "):]
    if not message:
        message = (f"Command '{obfuscate(command_to_string(result.command), secrets)}' "
                   f"failed with exit code {result.return_code}.")
    return message


# -- re-dispatching appctl itself ---------------------------------------------


def _flag(name, value):
    if value is True:
        return f"--{name}"
    if value is False:
        return f"--no-{name}"
    return f"--{name}={value}"


def runtime_flags(runtime):
    """Global flags reproducing the current runtime configuration."""
    flags = []
    for name, param in GLOBAL_PARAMETERS.items():
        if not param.runtime or name not in (runtime or {}):
            continue
        value = runtime[name]
        if value is None or value == param.default:
            continue
        if isinstance(value, (list, tuple)):
            flags.extend(_flag(name, item) for item in value)
        else:
            flags.append(_flag(name, value))
    return flags


def self_command(command, args=(), assoc=None, runtime=None):
    """argv that runs appctl ``command`` with the current runtime flags."""
    words = shlex.split(command) if isinstance(command, str) else list(command)
    words += [str(a) for a in args]
    words += [_flag(k, v) for k, v in (assoc or {}).items()]
    return [sys.executable, SCRIPT_PATH] + runtime_flags(runtime) + words


def self_environment(config_path=None, environ=None):
    env = dict(os.environ if environ is None else environ)
    if config_path:
        env[CONFIG_PATH_ENV] = str(config_path)
    return env


def launch_self(ctx, command, args=(), assoc=None, exit_on_error=True, return_detailed=False,
                parse=None, obfuscate_list=(), cwd=None):
    """Run an appctl command in a child process, preserving the runtime config.

    Returns the :class:`ProcessRun` (``return_detailed``) or the return code.
    With ``parse="json"`` the child's STDOUT is decoded as JSON first.
    """
    runtime = getattr(ctx, "runtime", None) or {}
    config = getattr(ctx, "config", None)
    argv = self_command(command, args, assoc, runtime)
    env = self_environment(getattr(config, "global_path", None))
    result = launch(argv, getattr(ctx, "output", None), exit_on_error=exit_on_error,
                    obfuscate_list=obfuscate_list, cwd=cwd, env=env)
    if parse == "json":
        result.stdout = parse_json(result.stdout)
    return result if return_detailed else result.return_code


def runcommand(ctx, command, return_=True, parse=None, exit_error=True, obfuscate_list=()):
    """Run an appctl command and return its result.

    ``return_`` selects ``"all"`` (the :class:`ProcessRun`), ``"stdout"`` (or
    ``True``), ``"stderr"`` or ``"return_code"``. ``parse="json"`` decodes
    STDOUT as JSON before it is returned.
    """
    result = launch_self(ctx, command, exit_on_error=exit_error, return_detailed=True,
                         parse=parse, obfuscate_list=obfuscate_list)
    if return_ == "all":
        return result
    if return_ == "stderr":
        return result.stderr.strip()
    if return_ == "return_code":
        return result.return_code
    if parse == "json":
        return result.stdout
    return result.stdout.strip()


def parse_json(text):
    """Decode JSON output; ``None`` when it is not valid JSON."""
    try:
        return json.loads(text)
    except (TypeError, ValueError):
        return None
"""Global runtime configuration parameters."""

import copy
from dataclasses import dataclass

STRICT_ARGS_ENV = "APPCTL_STRICT_ARGS_MODE"


@dataclass(frozen=True)
class GlobalParameter:
    name: str
    synopsis: str
    description: str
    default: object = None
    runtime: bool = True
    file: bool = True
    multiple: bool = False
    deprecated: str = None
    hidden: bool = False


def _file_only(name, description, default=None):
    return GlobalParameter(name, "", description, default, runtime=False, file=True)


GLOBAL_PARAMETERS = {
    p.name: p
    for p in (
        GlobalParameter("path", "--path=<path>", "Path to the application files.", None),
        GlobalParameter("url", "--url=<url>", "Pretend request came from given URL.", None),
        GlobalParameter("ssh", "--ssh=<[scheme:][user@]host|container>[:port][path]",
                        "Perform operation against a remote server over SSH.", None),
        GlobalParameter("http", "--http=<http>", "Perform operation against a remote install over HTTP.", None),
        GlobalParameter("user", "--user=<id|login|email>", "Set the user for the current request.", None),
        GlobalParameter("skip-plugins", "--skip-plugins[=<plugins>]", "Skip loading all or some plugins.", False),
        GlobalParameter("skip-themes", "--skip-themes[=<themes>]", "Skip loading all or some themes.", False),
        GlobalParameter("skip-packages", "--skip-packages", "Skip loading all installed packages.", False),
        GlobalParameter("require", "--require=<path>", "Load a file before running the command.", None),
        GlobalParameter("exec", "--exec=<php-code>", "Execute code before running the command.", None),
        GlobalParameter("context", "--context=<context>", "Load the application in a given context.", "cli"),
        _file_only("disabled_commands", "(Sub)commands to disable.", []),
        _file_only("projects_path", "Path where projects are stored."),
        _file_only("locale", "Locale to use.", "en_US"),
        _file_only("cert-email", "Email address used for certificate registration."),
        _file_only("env", "Environment the tool runs in."),
        _file_only("admin-email", "Email address of the administrator."),
        _file_only("sysctl", "Kernel parameters applied to containers."),
        _file_only("skip-tty", "Never allocate a TTY for remote commands.", False),
        _file_only("custom-compose", "Path to a custom compose file."),
        _file_only("installer_version", "Release channel of the installer.", "stable"),
        GlobalParameter("color", "--[no-]color", "Whether to colorize the output.", "auto"),
        GlobalParameter("debug", "--debug[=<group>]", "Show all errors and debug messages.", False,
                        file=False),
        GlobalParameter("prompt", "--prompt[=<assoc>]", "Prompt the user to enter values for all arguments.",
                        False, file=False),
        GlobalParameter("quiet", "--quiet", "Suppress informational messages.", False, file=False),
    )
}


def is_global_parameter(key):
    """True for global parameters that may be given as runtime flags."""
    param = GLOBAL_PARAMETERS.get(key)
    return param is not None and param.runtime


def is_file_parameter(key):
    param = GLOBAL_PARAMETERS.get(key)
    return param is not None and param.file


def visible_parameters():
    """Global parameters that may be shown in help output."""
    return {name: p for name, p in GLOBAL_PARAMETERS.items() if not p.hidden}


def deprecation_warnings(supplied):
    """Warning lines for every deprecated parameter used as a runtime flag."""
    return [
        f"Warning: The --{key} global parameter is deprecated."
        for key in supplied
        if key in GLOBAL_PARAMETERS and GLOBAL_PARAMETERS[key].deprecated is not None
    ]


def is_strict_mode(environ):
    return bool(environ.get(STRICT_ARGS_ENV))


def _arrayify(value):
    if value is None:
        return []
    return list(value) if isinstance(value, (list, tuple)) else [value]


def build_runtime_config(supplied, *layers):
    """Merge configuration over the defaults.

    ``layers`` are file-derived mappings from lowest to highest precedence
    (e.g. global config, project config, alias); only recognized
    file parameters are taken from them. ``supplied`` holds the runtime
    flags, which win over everything.
    """
    config = {name: copy.deepcopy(param.default) for name, param in GLOBAL_PARAMETERS.items()}
    for layer in layers:
        for key, value in (layer or {}).items():
            if is_file_parameter(key):
                config[key] = value
    config.update(supplied)
    config["disabled_commands"] = [str(c) for c in _arrayify(config.get("disabled_commands"))]
    return config
"""Loading of global/project YAML config files and alias definitions."""

import json
import os
import re
from dataclasses import dataclass, field

import yaml

from .errors import AppctlError

CONFIG_PATH_ENV = "APPCTL_CONFIG_PATH"
ROOT_DIR_ENV = "APPCTL_ROOT_DIR"
PACKAGES_DIR_ENV = "APPCTL_PACKAGES_DIR"
RUNTIME_ALIAS_ENV = "APPCTL_RUNTIME_ALIAS"

PROJECT_CONFIG_FILES = ("appctl.local.yml", "appctl.yml")
ALIAS_RE = re.compile(r"^@[A-Za-z0-9_.\-]+$")
ALL_ALIAS = "@all"
META_KEY = "_"

# Keys the global config file must always define, with their defaults.
REQUIRED_GLOBAL_KEYS = (("locale", "en_US"), ("installer_version", "stable"))


def is_alias(name):
    return isinstance(name, str) and bool(ALIAS_RE.match(name))


def alias_sort_key(name):
    return (name.lower(), name)


# -- locations -----------------------------------------------------------


def root_dir(environ):
    value = environ.get(ROOT_DIR_ENV)
    if value:
        return value
    return os.path.join(os.path.expanduser("~"), ".appctl")


def global_config_path(environ):
    value = environ.get(CONFIG_PATH_ENV)
    if value:
        return value
    return os.path.join(root_dir(environ), "config", "config.yml")


def packages_dir(environ):
    value = environ.get(PACKAGES_DIR_ENV)
    if value:
        return value
    return os.path.join(root_dir(environ), "packages")


def find_project_config(cwd):
    """Search upward from ``cwd``; the first directory with a config wins."""
    directory = os.path.abspath(cwd)
    while True:
        for name in PROJECT_CONFIG_FILES:
            candidate = os.path.join(directory, name)
            if os.path.isfile(candidate):
                return candidate
        parent = os.path.dirname(directory)
        if parent == directory:
            return None
        directory = parent


# -- auto-creation ---------------------------------------------------------


def _read_mapping(path):
    with open(path, encoding="utf-8") as handle:
        text = handle.read()
    try:
        data = yaml.safe_load(text)
    except yaml.YAMLError as exc:
        raise AppctlError(f"Unable to parse the config file '{path}': {exc}") from exc
    if data is None:
        data = {}
    if not isinstance(data, dict):
        raise AppctlError(f"The config file '{path}' must contain a YAML mapping.")
    return data, text


def ensure_global_config(path, strict=True):
    """Add missing required keys to the global config file, creating it.

    Write failures raise :class:`AppctlError` unless ``strict`` is false.
    """
    try:
        if os.path.exists(path):
            data, text = _read_mapping(path)
        else:
            data, text = {}, ""
        missing = [(k, v) for k, v in REQUIRED_GLOBAL_KEYS if k not in data]
        if not missing:
            return
        if text and not text.endswith("\n"):
            text += "\n"
        text += "".join(f"{key}: {value}\n" for key, value in missing)
        directory = os.path.dirname(path)
        if directory:
            os.makedirs(directory, exist_ok=True)
        with open(path, "w", encoding="utf-8") as handle:
            handle.write(text)
    except OSError as exc:
        if strict:
            reason = exc.strerror or str(exc)
            raise AppctlError(f"Unable to write the config file '{path}': {reason}.") from exc


# -- YAML loading with inheritance -------------------------------------------


def _merge(base, override, append_arrays):
    """Overlay ``override`` on ``base``; nested mappings merge recursively."""
    if isinstance(base, dict) and isinstance(override, dict):
        merged = dict(base)
        for key, value in override.items():
            merged[key] = _merge(base[key], value, append_arrays) if key in base else value
        return merged
    if append_arrays and isinstance(base, list) and isinstance(override, list):
        return base + override
    return override


def _absolutize_alias_paths(data, directory):
    for key, value in data.items():
        if is_alias(key) and isinstance(value, dict):
            path = value.get("path")
            if isinstance(path, str) and path and "ssh" not in value:
                value["path"] = os.path.normpath(os.path.join(directory, os.path.expanduser(path)))


def load_config_file(path, accumulated=None, _seen=None):
    """Merge the YAML file at ``path`` (and its ancestors) over ``accumulated``."""
    accumulated = dict(accumulated or {})
    if not path:
        return accumulated
    path = os.path.abspath(path)
    seen = set(_seen or ())
    if path in seen or not os.path.isfile(path):
        return accumulated
    seen.add(path)
    try:
        data, _ = _read_mapping(path)
    except OSError:
        return accumulated
    directory = os.path.dirname(path)
    meta = data.pop(META_KEY, None)
    meta = meta if isinstance(meta, dict) else {}
    inherit = meta.get("inherit")
    if isinstance(inherit, str) and inherit:
        base = os.path.join(directory, os.path.expanduser(inherit))
        accumulated = load_config_file(base, accumulated, seen)
    _absolutize_alias_paths(data, directory)
    return _merge(accumulated, data, meta.get("merge") is True)


# -- aliases -------------------------------------------------------------------


def runtime_aliases(environ, cwd):
    raw = environ.get(RUNTIME_ALIAS_ENV)
    if not raw:
        return {}
    try:
        decoded = json.loads(raw)
    except ValueError:
        return {}
    if not isinstance(decoded, dict):
        return {}
    aliases = {k: v for k, v in decoded.items() if is_alias(k)}
    _absolutize_alias_paths(aliases, cwd)
    return aliases


def collect_aliases(config, extra=None):
    """Return ``{name: definition}``, registering ``@all`` when needed.

    A definition is either a mapping of connection parameters or a list
    of alias names (a group).
    """
    aliases = {}
    for key, value in list(config.items()) + list((extra or {}).items()):
        if not is_alias(key):
            continue
        if isinstance(value, list):
            aliases[key] = [str(v) for v in value]
        elif isinstance(value, dict):
            aliases[key] = dict(value)
        elif value is None:
            aliases[key] = {}
        else:
            aliases[key] = value
    if aliases and ALL_ALIAS not in aliases:
        aliases[ALL_ALIAS] = None  # implicit: every registered alias
    return aliases


# -- entry point ---------------------------------------------------------------


@dataclass
class LoadedConfig:
    global_path: str = None
    project_path: str = None
    global_config: dict = field(default_factory=dict)
    merged: dict = field(default_factory=dict)
    aliases: dict = field(default_factory=dict)
    packages_dir: str = None


def load(environ, cwd=None):
    cwd = cwd or os.getcwd()
    global_path = global_config_path(environ)
    explicit = bool(environ.get(CONFIG_PATH_ENV) or environ.get(ROOT_DIR_ENV))
    ensure_global_config(global_path, strict=explicit)
    global_config = load_config_file(global_path)
    project_path = find_project_config(cwd)
    if project_path and os.path.abspath(project_path) == os.path.abspath(global_path):
        project_path = None
    merged = load_config_file(project_path, global_config)
    return LoadedConfig(
        global_path=global_path,
        project_path=project_path,
        global_config=global_config,
        merged=merged,
        aliases=collect_aliases(merged, runtime_aliases(environ, cwd)),
        packages_dir=packages_dir(environ),
    )
"""Append-only file log of every invocation at ``<root>/logs/appctl.log``."""

import os
import re
import shlex
from datetime import datetime, timezone

from . import PROGRAM_NAME

LOG_DIR = "logs"
LOG_FILE = f"{PROGRAM_NAME}.log"
DELIMITER = "-" * 72
REDACTED = "[REDACTED]"

# ``--key=value`` arguments whose value must never reach the disk.
SENSITIVE_KEY_RE = re.compile(r"pass|pwd|secret|token|api[-_]?key|private[-_]?key|auth|credential",
                              re.IGNORECASE)


def log_path(root_dir):
    return os.path.join(root_dir, LOG_DIR, LOG_FILE)


def utc_timestamp(now=None):
    """ISO 8601 UTC timestamp with second precision, e.g. ``2024-01-31T12:00:00Z``."""
    now = now or datetime.now(timezone.utc)
    return now.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def redact_argv(argv):
    """Replace the values of sensitive ``--key=value`` arguments."""
    redacted = []
    for index, token in enumerate(argv):
        if token == "--":
            redacted.extend(argv[index:])
            break
        if token.startswith("--") and "=" in token:
            key = token[2:].split("=", 1)[0]
            if SENSITIVE_KEY_RE.search(key):
                token = f"--{key}={REDACTED}"
        redacted.append(token)
    return redacted


class FileLogger:
    """Writes timestamped entries; write failures silently disable logging."""

    def __init__(self, path, enabled=True):
        self.path = path
        self.enabled = bool(enabled and path)

    def start_invocation(self, argv):
        """Write the delimiter line and the (redacted) command line."""
        command = shlex.join([PROGRAM_NAME] + redact_argv(list(argv)))
        self._append(f"{DELIMITER}\n[{utc_timestamp()}] Command: {command}\n")

    def write(self, text):
        """Append one entry; every line of it carries the timestamp."""
        stamp = utc_timestamp()
        self._append("".join(f"[{stamp}] {line}\n" for line in str(text).split("\n")))

    def _append(self, data):
        if not self.enabled:
            return
        try:
            directory = os.path.dirname(self.path)
            if directory:
                os.makedirs(directory, exist_ok=True)
            with open(self.path, "a", encoding="utf-8") as handle:
                handle.write(data)
        except OSError:
            self.enabled = False
"""Splitting raw argv into positional, associative and global arguments."""

from dataclasses import dataclass, field

from .runtime_config import is_global_parameter

END_OF_OPTIONS = "--"


def is_assoc_token(token):
    """True for ``--key``, ``--key=value`` and ``--no-key`` tokens."""
    return token.startswith("--") and len(token) > 2


def parse_assoc_token(token):
    """Return ``(key, value)`` for an associative token.

    ``--key=value`` yields the string value, ``--no-key`` yields ``False``
    and a bare ``--key`` yields ``True``.
    """
    body = token[2:]
    if "=" in body:
        key, value = body.split("=", 1)
        return key, value
    if body.startswith("no-"):
        return body[3:], False
    return body, True


@dataclass
class ParsedArguments:
    positional: list = field(default_factory=list)
    assoc: dict = field(default_factory=dict)
    runtime: dict = field(default_factory=dict)


def parse_argv(argv, strict=False):
    """Classify every argv token.

    Global parameters become runtime configuration. In strict mode only
    those appearing before the first positional token are treated as
    global; afterwards every argument is command-specific.
    """
    parsed = ParsedArguments()
    end_of_options = False
    seen_positional = False
    for token in argv:
        if not end_of_options and token == END_OF_OPTIONS:
            end_of_options = True
            continue
        if end_of_options or not is_assoc_token(token):
            parsed.positional.append(token)
            seen_positional = True
            continue
        key, value = parse_assoc_token(token)
        if is_global_parameter(key) and not (strict and seen_positional):
            parsed.runtime[key] = value
        else:
            parsed.assoc[key] = value
    return parsed

